INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a028697786379c39fe2e5fec2c736c49f846f9f/content/books/zizhi-tongjian/vol-284/year-0944/part-01/sources/library/jiuwudaishi-082-944-february/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p002000；EPUB电子本，纸本及异文待核", "id": "04119ebd-bad6-579c-8a8b-4ee9ebfb8588"}, {"title": "旧五代史·卷八十二", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a028697786379c39fe2e5fec2c736c49f846f9f/content/books/zizhi-tongjian/vol-284/year-0944/part-01/sources/library/jiuwudaishi-082-944-march/source.txt", "note": "《旧五代史》卷八十二，段落 jiu-wudaishi-205deb4a7860-p002001；EPUB电子本，纸本及异文待核", "id": "645b500c-7bcf-5ab3-bfdf-267b6ab11ffb"}, {"title": "辽史·卷四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a028697786379c39fe2e5fec2c736c49f846f9f/content/books/zizhi-tongjian/vol-284/year-0944/part-01/sources/library/liaoshi-004-944-february/source.txt", "note": "《辽史》卷四，段落 liaoshi-7cd182a20e67-p000542；EPUB电子本，纸本及异文待核", "id": "c2d2017d-fb8a-550c-9dfe-95f1739bef5e"}, {"title": "资治通鉴·后晋纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a028697786379c39fe2e5fec2c736c49f846f9f/content/books/zizhi-tongjian/vol-284/year-0944/part-01/sources/library/tongjian-284-944-february-march/source.txt", "note": "《资治通鉴》后晋纪五，段落 zizhi-tongjian-a63549944a71-p003373；电子底本待考，分段待核", "id": "d889a837-7365-5b21-a51a-aa63f15c3d5a"}, {"title": "新五代史·卷四十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a028697786379c39fe2e5fec2c736c49f846f9f/content/books/zizhi-tongjian/vol-284/year-0944/part-01/sources/library/xinwudaishi-047-li-qiong/source.txt", "note": "《新五代史》卷四十七，段落 xin-wudaishi-b08f244b9241-p001827；EPUB电子本，纸本及异文待核", "id": "178935f9-baa7-5cdd-983e-42b090b5bd28"}, {"title": "新五代史·卷九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/xinwudaishi-009-944-january/source.txt", "note": "《新五代史》卷九，段落 xin-wudaishi-b08f244b9241-p000335；EPUB电子本，纸本及异文待核", "id": "71c7fc99-919d-58e5-acc1-c401819fcdc4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "石赟", "aliases": ["石贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋前保义节度使。944年二月甲辰朔奉命驻守麻家口，戊午又奉诏分兵驻郓州。《辽史》同场部署写石斌，姓名异文尚待校核，未据此另作同人合并。生卒年未载。", "biography": null, "status": "draft", "id": "1f3ee37d-40c6-57ea-bdf6-9c36eb3f5658"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "白再荣", "aliases": ["白再榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋护圣都指挥使。944年二月甲辰朔奉命驻守马家口。原地名与石赟所守麻家口分别保留，不自动混写。生卒年本批未核。", "biography": null, "status": "draft", "id": "91caa219-2e64-565f-b15f-a4402d8c7b3d"}, {"name": "安彦威", "aliases": ["安彥威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安彦威，侍卫马军都指挥使、宁国节度使。", "biography": null, "status": "draft", "id": "fe8191f2-7077-5aac-806f-7a165fcf9b34"}, {"name": "周儒（后晋博州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋博州刺史，944年正月投降契丹，并与杨光远通使。颜衎的奏报称其引契丹从马家口渡河，蔡行遇被擒。未证与888年魏博被俘将领周儒同人，分别建档。", "biography": null, "status": "draft", "id": "6c8c96d3-e567-5c7c-bc3b-4486d1d6ba6f"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "梁汉璋", "aliases": ["梁漢璋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州人，后晋陈州防御使。944年二月乙巳与李守贞、皇甫遇、薛怀让等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f62e9bd0-d874-521f-b4ff-27f731b77abb"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "石公霸", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋先锋指挥使。944年二月丙午在戚城与高行周、符彦卿一起遭契丹围攻，石重贵亲自率军救援后解围。生卒年未载。", "biography": null, "status": "draft", "id": "3dd17da6-20c2-5ee4-b1e4-4af3740eb22a"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "李琼（后晋将领）", "aliases": ["李瓊（后晋将领）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋将领，沧州饶安人，曾与石敬瑭在李嗣源部下效力。出帝时任棣州刺史，拒绝杨光远招降；944年二月击退杨光远围城。《旧五代史》此役作冀州，与主书棣州并列待核。与马殷部下李琼分别建档。", "biography": null, "status": "draft", "id": "3910d1ce-6f82-5a9d-af47-aceb5d344609"}, {"name": "王君怀", "aliases": ["王君懷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阶州、成州义军指挥使。944年二月率部千余人投降后蜀，请求作向导攻取阶州、成州。生卒年未载。", "biography": null, "status": "draft", "id": "bc7565be-dc99-5d7c-a41d-0149246a80e7"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "李守超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《旧五代史》记944年三月澶州交战中率数百骑兵攻击契丹、使其稍退的晋方将领。姓名原文保留，纸本及是否有异名尚待校核，未直接并入李守贞。生卒年未载。", "biography": null, "status": "draft", "id": "0e7fa483-8a3b-5901-9083-72fa24972d5a"}, {"name": "安重怀", "aliases": ["安重懷"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "后晋护圣第二军都指挥使。《旧五代史》记944年三月交战中因被指临阵怯战、丢失兵器，与乌韩七、何彦超被斩。生卒具体月日本批未核。", "biography": null, "status": "draft", "id": "0fe8adb1-eba8-560c-980b-241a60f1afa1"}, {"name": "乌韩七", "aliases": ["烏韓七"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "后晋护圣军指挥使。《旧五代史》记944年三月交战中因被指临阵怯战、丢失兵器，与安重怀、何彦超被斩。姓名字形与纸本待核。", "biography": null, "status": "draft", "id": "f50db97c-4589-51d0-9910-33148a00b1b7"}, {"name": "何彦超", "aliases": ["何彥超"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "后晋监军。《旧五代史》记944年三月交战中因被指临阵怯战、丢失兵器，与安重怀、乌韩七被斩。生卒具体日期未载。", "biography": null, "status": "draft", "id": "71bc655c-990f-5df5-8649-b963ef3bb003"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

